using System;using System.Linq;using System.Threading.Tasks;using CTXD.Client.Features.FirstPlayable;using CTXD.Client.Networking;using UnityEngine;
namespace CTXD.Client.Features.Social { public sealed class KfwdPanel:MonoBehaviour { ApiClient _api;Action<string> _status;RectTransform _window;KfwdView _view;GeneralRosterResponse _roster;int[] _selected=Array.Empty<int>();public static KfwdPanel Open(RectTransform host,ApiClient api,Action<string> status){var go=new GameObject("KfwdPanel");go.transform.SetParent(host,false);var p=go.AddComponent<KfwdPanel>();p._api=api;p._status=status;p.Build();_=p.Refresh();return p;}void Build(){var b=LegacyUiFactory.Panel(transform,"KfwdBlocker",Vector2.zero,Vector2.one,new Color(0,0,0,.82f));_window=LegacyUiFactory.PixelPanel(b,"KfwdWindow",240,65,800,620,new Color(.05f,.03f,.015f,1));}async Task Refresh(){try{_view=await _api.GetKfwdAsync();_roster=await _api.GetGeneralsAsync();Draw();}catch(Exception e){_status(e.Message);Destroy(gameObject);}}void Draw(){LegacyUiFactory.DestroyChildren(_window);LegacyUiFactory.PixelLabel(_window,"KFWD - SEASON "+_view.seasonNo,22,TextAnchor.MiddleCenter,new Color(1,.8f,.3f),220,12,360,34);LegacyUiFactory.PixelButton(_window,"Close",710,16,65,27,()=>Destroy(gameObject));LegacyUiFactory.PixelLabel(_window,"State "+_view.globalState+"   W "+_view.wins+" / L "+_view.losses+"   Tickets "+_view.tickets,16,TextAnchor.MiddleCenter,Color.white,100,55,600,28);var y=100;foreach(var g in (_roster?.military??Array.Empty<GeneralView>()).Take(8)){var id=g.id;var selected=_selected.Contains(id);LegacyUiFactory.PixelButton(_window,(selected?"* ":"")+g.name+" Lv"+g.level,55,y,300,30,()=>{_selected=selected?_selected.Where(x=>x!=id).ToArray():_selected.Append(id).ToArray();Draw();});y+=36;}if(!_view.signed&&_view.globalState==20)LegacyUiFactory.PixelButton(_window,"Sign up",440,115,230,34,()=>Submit(false));else if(_view.signed&&!_view.synced&&_view.globalState==50)LegacyUiFactory.PixelButton(_window,"Sync formation",440,115,230,34,()=>Submit(true));else LegacyUiFactory.PixelLabel(_window,_view.synced?"Formation synchronized":"Registration closed",16,TextAnchor.MiddleCenter,Color.gray,430,115,250,34);if(_view.match!=null){LegacyUiFactory.PixelLabel(_window,"Round "+_view.match.round+" - Opponent "+_view.match.opponentPlayerId,17,TextAnchor.MiddleCenter,Color.white,410,190,300,32);if(_view.match.battleId>0&&_view.match.state==1){var battle=_view.match.battleId;LegacyUiFactory.PixelButton(_window,"Open battle",450,235,220,38,async()=>{try{await _api.GetBattleAsync(battle);_status("KFWD battle "+battle+" ready");}catch(Exception e){_status(e.Message);}});}}}async void Submit(bool sync){try{if(_selected.Length==0)throw new Exception("Select at least one general");_view=sync?await _api.SyncKfwdAsync(_selected):await _api.SignupKfwdAsync(_selected);_status(sync?"KFWD formation synced":"KFWD signup complete");await Refresh();}catch(Exception e){_status(e.Message);}}} }
